eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   collectionBySlug: () => (/* binding */ collectionBySlug),\n/* harmony export */   collections: () => (/* binding */ collections)\n/* harmony export */ });\nconst BANNER_WIDTH = 1800;\nconst BANNER_HEIGHT = 620;\nfunction build(seed) {\n    return {\n        slug: seed.slug,\n        name: seed.name,\n        heading: seed.heading,\n        description: seed.description,\n        seoContent: seed.seoContent,\n        group: seed.group,\n        bannerImage: {\n            url: `/images/banners/${seed.banner ?? seed.slug}.png`,\n            alt: seed.bannerAlt ?? `Pashmore ${seed.name.toLowerCase()} collection — handcrafted Indian textiles`,\n            width: BANNER_WIDTH,\n            height: BANNER_HEIGHT\n        },\n        includeCategorySlugs: seed.includeCategorySlugs,\n        relatedSlugs: seed.relatedSlugs,\n        faqs: seed.faqs,\n        featured: seed.featured,\n        hidden: seed.hidden\n    };\n}\nconst SEEDS = [\n    /* ---------------------------------------------------------------- *\n   * Women\n   * ---------------------------------------------------------------- */ {\n        slug: 'womens-shawls',\n        name: \"Women's Shawls\",\n        heading: \"Women's Shawls\",\n        description: 'Handwoven shawls for women in pure Pashmina, cashmere and fine Kashmiri wool — from undyed heritage pieces to fully embroidered occasion shawls.',\n        group: 'women',\n        featured: true,\n        relatedSlugs: [\n            'womens-pashmina',\n            'womens-stoles',\n            'kashmiri-collection',\n            'wedding-collection'\n        ],\n        seoContent: [\n            'A shawl is the most useful thing in an Indian wardrobe and the hardest to buy well. What separates one shawl from another is not the pattern but the fibre and the loom: the micron count of the pashm, whether it was spun on a charkha or by machine, and how many picks per inch the weaver was willing to work at.',\n            'Our women’s shawls are made in three weights. Pure Pashmina at around 180 grams for occasion and evening; cashmere at 250–320 grams for daily winter wear; and Kashmiri handloom wool above 400 grams for genuine cold. Every piece is finished by hand and ships with a certificate recording the weaver’s name.',\n            'If you are buying your first, start with an undyed piece — the Ivory Heritage or the Warm Beige Ring Pashmina. Undyed cloth hides nothing, so it is the honest way to judge quality, and neutrals outlast every trend.'\n        ],\n        faqs: [\n            {\n                question: 'What is the difference between a shawl and a stole?',\n                answer: 'Width. A shawl is roughly 100–110 cm wide and is meant to wrap; a stole is 70 cm or narrower and is meant to hang. Both are typically 200–220 cm long.'\n            },\n            {\n                question: 'Which shawl is warmest?',\n                answer: 'Kashmiri handloom wool is the warmest by weight, followed by brushed cashmere. Pure Pashmina is the warmest relative to its weight — it is remarkably light for how much heat it holds.'\n            },\n            {\n                question: 'How should I store a shawl between seasons?',\n                answer: 'Folded flat in a breathable cotton or muslin bag, never on a hanger, with a cedar block nearby. Refold along a different line each year so permanent creases do not set.'\n            }\n        ]\n    },\n    {\n        slug: 'womens-pashmina',\n        name: \"Women's Pashmina\",\n        heading: \"Women's Pure Pashmina\",\n        description: 'Certified pure Pashmina for women — hand-combed Changthangi fibre, charkha-spun and handwoven in Kashmir.',\n        group: 'women',\n        featured: true,\n        relatedSlugs: [\n            'pure-pashmina',\n            'womens-shawls',\n            'pashmina',\n            'luxury-collection'\n        ],\n        seoContent: [\n            'Pashmina is not a style of shawl. It is a fibre: the winter underfleece of the Changthangi goat, combed by hand each spring on the Changthang plateau at over 4,000 metres. At 12–15 microns it is roughly half the diameter of fine merino, which is why a Pashmina shawl can weigh under 200 grams and still keep you warm.',\n            'Everything in this collection is pure pashm — no blending, no substitution. Each piece is spun on a hand charkha, woven on a wooden handloom and finished by hand, and ships with documentation recording the fibre grade and the weaver.'\n        ]\n    },\n    {\n        slug: 'womens-stoles',\n        name: \"Women's Stoles\",\n        description: 'Lightweight stoles that layer across seasons — cashmere, Pashmina and handloom wool, cut narrow to drape.',\n        group: 'women',\n        relatedSlugs: [\n            'stoles',\n            'womens-scarves',\n            'womens-shawls'\n        ]\n    },\n    {\n        slug: 'womens-scarves',\n        name: \"Women's Scarves\",\n        description: 'Fine scarves in Pashmina-silk blends, cashmere and brushed merino — the easiest way into handwoven Indian cloth.',\n        group: 'women',\n        relatedSlugs: [\n            'scarves',\n            'womens-stoles',\n            'gifts-for-her'\n        ]\n    },\n    {\n        slug: 'womens-dupattas',\n        name: 'Dupattas',\n        heading: 'Hand-Embroidered Dupattas',\n        description: 'Dupattas in Banarasi silk, cotton silk and Kashmiri embroidery — for occasion dressing and everyday ethnic wear.',\n        group: 'women',\n        relatedSlugs: [\n            'womens-suits',\n            'wedding-collection',\n            'kashmiri-collection'\n        ],\n        seoContent: [\n            'The dupatta carries more design weight than anything else in an Indian outfit — it is the piece people actually look at. Ours are made in three traditions: Kashmiri tilla and sozni from Srinagar, chikankari from Lucknow, and figured zari silk from Varanasi.',\n            'A dupatta is typically 90 cm × 230 cm. Occasion pieces are heavier and hold a pleat; everyday cotton silk is lighter and moves more.'\n        ]\n    },\n    {\n        slug: 'womens-dresses',\n        name: \"Women's Dresses\",\n        description: 'Modern ethnic silhouettes cut from handwoven Indian cloth. New pieces arriving this season.',\n        group: 'women',\n        relatedSlugs: [\n            'womens-suits',\n            'womens-shawls'\n        ]\n    },\n    {\n        slug: 'womens-suits',\n        name: \"Women's Suits\",\n        description: 'Tailored suit sets in handloom cotton silk and fine wool, made to be worn with a Pashmore dupatta.',\n        group: 'women',\n        relatedSlugs: [\n            'womens-dupattas',\n            'womens-dresses'\n        ]\n    },\n    /* ---------------------------------------------------------------- *\n   * Men\n   * ---------------------------------------------------------------- */ {\n        slug: 'mens-shawls',\n        name: \"Men's Shawls\",\n        heading: \"Men's Shawls\",\n        description: 'Men’s shawls in pure Pashmina and Kashmiri handloom wool, cut long and narrow to hang cleanly from the shoulder.',\n        group: 'men',\n        featured: true,\n        relatedSlugs: [\n            'mens-stoles',\n            'mens-jackets',\n            'gifts-for-him',\n            'pure-pashmina'\n        ],\n        seoContent: [\n            'A men’s shawl is cut differently from a women’s: more length, less width, so it falls in two straight columns rather than wrapping. Traditionally it is worn over a bandhgala or kurta, folded once lengthwise and draped over one shoulder.',\n            'We make them in two weights. Pure Pashmina for evening and occasion, where lightness matters more than bulk; and Kashmiri handloom wool at 400 grams and above for genuine winter, brushed twice so it softens with wear rather than wearing out.'\n        ],\n        faqs: [\n            {\n                question: 'What length should a men’s shawl be?',\n                answer: 'A 110 × 220 cm shawl suits most men. Anything shorter tends to sit awkwardly when folded lengthwise over the shoulder.'\n            },\n            {\n                question: 'Can a men’s shawl be worn with western tailoring?',\n                answer: 'Yes — worn as an oversized scarf over an overcoat it works well. For that use, a narrower stole is usually easier to manage.'\n            }\n        ]\n    },\n    {\n        slug: 'mens-stoles',\n        name: \"Men's Stoles\",\n        description: 'Narrow-cut stoles in cashmere and Pashmina, finished without fringe so they sit flat under a coat collar.',\n        group: 'men',\n        relatedSlugs: [\n            'stoles',\n            'mens-scarves',\n            'mens-shawls'\n        ]\n    },\n    {\n        slug: 'mens-scarves',\n        name: \"Men's Scarves\",\n        description: 'Everyday luxury scarves in merino wool and cashmere — hard-wearing, unfussy and easy to give.',\n        group: 'men',\n        relatedSlugs: [\n            'scarves',\n            'mens-stoles',\n            'gifts-for-him'\n        ]\n    },\n    {\n        slug: 'mens-jackets',\n        name: \"Men's Jackets\",\n        description: 'Nehru jackets and unstructured outerwear cut from handloom wool, with hand-worked buttonholes.',\n        group: 'men',\n        relatedSlugs: [\n            'mens-shawls',\n            'heritage-collection',\n            'wedding-collection'\n        ]\n    },\n    {\n        slug: 'mens-accessories',\n        name: \"Men's Accessories\",\n        description: 'Pocket squares, mufflers and the small pieces that finish an outfit.',\n        group: 'men',\n        relatedSlugs: [\n            'accessories',\n            'gifts-for-him',\n            'corporate-gifts'\n        ]\n    },\n    /* ---------------------------------------------------------------- *\n   * Aggregate categories\n   * ---------------------------------------------------------------- */ {\n        slug: 'shawls',\n        name: 'Shawls',\n        description: 'Every Pashmore shawl, for women and men — Pashmina, cashmere and Kashmiri handloom wool.',\n        group: 'category',\n        includeCategorySlugs: [\n            'womens-shawls',\n            'mens-shawls',\n            'womens-pashmina'\n        ],\n        relatedSlugs: [\n            'womens-shawls',\n            'mens-shawls',\n            'pashmina',\n            'stoles'\n        ]\n    },\n    {\n        slug: 'stoles',\n        name: 'Stoles',\n        description: 'Narrow-cut stoles across the collection, in Pashmina, cashmere and handloom wool.',\n        group: 'category',\n        includeCategorySlugs: [\n            'womens-stoles',\n            'mens-stoles'\n        ],\n        relatedSlugs: [\n            'shawls',\n            'scarves',\n            'womens-stoles',\n            'mens-stoles'\n        ]\n    },\n    {\n        slug: 'scarves',\n        name: 'Scarves',\n        description: 'Fine scarves in merino, cashmere and Pashmina-silk blends for women and men.',\n        group: 'category',\n        includeCategorySlugs: [\n            'womens-scarves',\n            'mens-scarves'\n        ],\n        relatedSlugs: [\n            'stoles',\n            'womens-scarves',\n            'mens-scarves'\n        ]\n    },\n    {\n        slug: 'accessories',\n        name: 'Accessories',\n        description: 'Pocket squares, boxed sets and the finishing pieces of the collection.',\n        group: 'category',\n        includeCategorySlugs: [\n            'mens-accessories'\n        ],\n        relatedSlugs: [\n            'mens-accessories',\n            'gifting'\n        ]\n    },\n    {\n        slug: 'gift-sets',\n        name: 'Gift Sets',\n        banner: 'gifting',\n        description: 'Curated sets presented in Pashmore’s hand-bound boxes with a craft certificate for every piece.',\n        group: 'gifting',\n        relatedSlugs: [\n            'gifting',\n            'luxury-gift-boxes',\n            'wedding-gifts'\n        ]\n    },\n    /* ---------------------------------------------------------------- *\n   * Merchandising collections\n   * ---------------------------------------------------------------- */ {\n        slug: 'new-arrivals',\n        name: 'New Arrivals',\n        description: 'The latest pieces to come off our looms — fresh expressions of timeless craftsmanship.',\n        group: 'collections',\n        featured: true,\n        relatedSlugs: [\n            'best-sellers',\n            'pure-pashmina',\n            'luxury-collection'\n        ]\n    },\n    {\n        slug: 'best-sellers',\n        name: 'Best Sellers',\n        heading: 'Most Loved',\n        description: 'The pieces our customers return to — ranked by what actually sells, not by what we would like to sell.',\n        group: 'collections',\n        featured: true,\n        relatedSlugs: [\n            'new-arrivals',\n            'womens-shawls',\n            'mens-shawls'\n        ]\n    },\n    {\n        slug: 'heritage-collection',\n        name: 'Heritage Collection',\n        description: 'Pieces made to the specifications our workshop used before 1980 — the same fibre grades, the same looms, the same finishing.',\n        group: 'collections',\n        featured: true,\n        relatedSlugs: [\n            'kashmiri-collection',\n            'pure-pashmina',\n            'luxury-collection'\n        ],\n        seoContent: [\n            'The Heritage Collection exists because we still have the pattern books. When our workshop was founded in Srinagar, weavers recorded fibre grade, sett, pick count and dye recipe for every commission. Those books survived, and these pieces are made to them.',\n            'Nothing here is a reproduction. The looms are the same design, the talim scripts are the originals, and several of the weavers learned from the men whose names appear in the ledgers.'\n        ]\n    },\n    {\n        slug: 'fine-wool',\n        name: 'Fine Wool',\n        description: 'Merino, cashmere and Kashmiri handloom wool — everyday luxury that is built to be worn hard.',\n        group: 'collections',\n        relatedSlugs: [\n            'pure-pashmina',\n            'shawls',\n            'scarves'\n        ]\n    },\n    {\n        slug: 'pure-pashmina',\n        name: 'Pure Pashmina',\n        heading: 'Pure Pashmina',\n        description: 'Nothing blended, nothing substituted. Hand-combed Changthangi fibre, charkha-spun and handwoven in Kashmir.',\n        group: 'collections',\n        featured: true,\n        relatedSlugs: [\n            'pashmina',\n            'womens-pashmina',\n            'kashmiri-collection',\n            'heritage-collection'\n        ],\n        seoContent: [\n            'Most cloth sold as \"pashmina\" is viscose, or wool with a small percentage of pashm blended in. Pure Pashmina means the yarn is entirely the underfleece of the Changthangi goat, hand-combed rather than shorn, and spun on a charkha rather than a mill frame — machine spinning breaks fibre this fine.',\n            'Every piece in this collection carries a GI-registered craft certificate recording micron grade, loom number and the name of the weaver who finished it. If a shawl cannot tell you those four things, it is not pure Pashmina.'\n        ],\n        faqs: [\n            {\n                question: 'How can I tell pure Pashmina from a blend?',\n                answer: 'Burn test aside, look for irregularity: hand-spun yarn varies slightly in thickness, so the weave is never perfectly uniform. Machine-made \"pashmina\" is flawless, glossy and cold to the touch. Genuine pashm feels warm immediately and has a matte, slightly hazy surface.'\n            },\n            {\n                question: 'Does the ring test really work?',\n                answer: 'For fine shawls, largely yes — cloth woven from sub-14-micron fibre will pass through a wedding ring. It does not work on heavier or embroidered pieces, and a thin viscose scarf will also pass, so use it alongside other checks.'\n            },\n            {\n                question: 'Why is pure Pashmina expensive?',\n                answer: 'One goat yields around 150 grams of usable fibre per year, and a shawl needs the yield of three to four goats plus six weeks on a handloom. The cost is almost entirely fibre and labour.'\n            }\n        ]\n    },\n    {\n        slug: 'kashmiri-collection',\n        name: 'Kashmiri Collection',\n        description: 'Sozni, kani, jamawar and tilla — the four great needle and loom crafts of the Kashmir valley.',\n        group: 'collections',\n        featured: true,\n        relatedSlugs: [\n            'heritage-collection',\n            'pure-pashmina',\n            'wedding-collection'\n        ],\n        seoContent: [\n            'Kashmir’s textile crafts divide into what is built into the cloth and what is added to it. Kani is woven — the pattern is constructed thread by thread on small wooden bobbins. Sozni, tilla and papier-mâché work are embroidered onto a finished ground.',\n            'Kani is the rarer and the slower. A full-field kani shawl can take two weavers close to two years, working from a coded pattern script called a talim that only trained weavers can read.'\n        ]\n    },\n    {\n        slug: 'wedding-collection',\n        name: 'Wedding Collection',\n        description: 'Bridal and occasion pieces — kani, tilla and Banarasi zari, made to be kept and given again.',\n        group: 'collections',\n        featured: true,\n        relatedSlugs: [\n            'wedding-gifts',\n            'kashmiri-collection',\n            'luxury-collection'\n        ]\n    },\n    {\n        slug: 'luxury-collection',\n        name: 'Luxury Collection',\n        description: 'Our most demanding work — the pieces that occupy a loom for months and leave the workshop numbered.',\n        group: 'collections',\n        relatedSlugs: [\n            'heritage-collection',\n            'kashmiri-collection',\n            'pure-pashmina'\n        ]\n    },\n    {\n        slug: 'pashmina',\n        name: 'Pashmina',\n        heading: 'Pashmina',\n        description: 'Every Pashmina piece at Pashmore — shawls, stoles, scarves and wraps in pure pashm and Pashmina-silk blends.',\n        group: 'collections',\n        featured: true,\n        relatedSlugs: [\n            'pure-pashmina',\n            'womens-pashmina',\n            'kashmiri-collection',\n            'shawls'\n        ]\n    },\n    /* ---------------------------------------------------------------- *\n   * Gifting\n   * ---------------------------------------------------------------- */ {\n        slug: 'gifting',\n        name: 'Gifting',\n        heading: 'The Art of Gifting',\n        description: 'Thoughtfully crafted pieces for moments worth remembering, presented in hand-bound boxes.',\n        group: 'gifting',\n        featured: true,\n        relatedSlugs: [\n            'gifts-for-her',\n            'gifts-for-him',\n            'wedding-gifts',\n            'corporate-gifts'\n        ]\n    },\n    {\n        slug: 'gifts-for-her',\n        name: 'Gifts for Her',\n        description: 'Shawls, wraps and scarves chosen to be given — every one with a craft certificate and a hand-written card.',\n        group: 'gifting',\n        relatedSlugs: [\n            'gifting',\n            'womens-shawls',\n            'luxury-gift-boxes'\n        ]\n    },\n    {\n        slug: 'gifts-for-him',\n        name: 'Gifts for Him',\n        description: 'Men’s shawls, stoles and accessories that will still be worn in twenty years.',\n        group: 'gifting',\n        relatedSlugs: [\n            'gifting',\n            'mens-shawls',\n            'corporate-gifts'\n        ]\n    },\n    {\n        slug: 'wedding-gifts',\n        name: 'Wedding Gifts',\n        description: 'Trousseau shawls and matched sets — the presents that get passed down rather than put away.',\n        group: 'gifting',\n        relatedSlugs: [\n            'wedding-collection',\n            'gifting',\n            'luxury-gift-boxes'\n        ]\n    },\n    {\n        slug: 'corporate-gifts',\n        name: 'Corporate Gifts',\n        description: 'Volume gifting in handwoven cloth, with optional debossed branding and individual dispatch.',\n        group: 'gifting',\n        relatedSlugs: [\n            'gifting',\n            'gifts-for-him',\n            'luxury-gift-boxes'\n        ],\n        seoContent: [\n            'Corporate gifting usually fails for the same reason: the recipient can tell how little thought went into it. A handwoven stole with the weaver’s name inside the care label reads differently.',\n            'We supply from ten pieces upwards, box individually, and can deboss a logo onto the lid or weave a custom care label into each piece. Lead time is four weeks from artwork approval; dispatch to multiple addresses is standard.'\n        ]\n    },\n    {\n        slug: 'luxury-gift-boxes',\n        name: 'Luxury Gift Boxes',\n        description: 'Hand-bound presentation boxes made in Srinagar, with muslin sleeve, craft certificate and message card.',\n        group: 'gifting',\n        relatedSlugs: [\n            'gifting',\n            'gifts-for-her',\n            'wedding-gifts'\n        ]\n    }\n];\nconst collections = SEEDS.map(build);\nconst collectionBySlug = new Map(collections.map((c)=>[\n        c.slug,\n        c\n    ]));\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./src/data/collections.ts\n");

